-- 21 · 2026-12-21 · Os que esperaram
insert into public.devocionais_agendados
  (publicar_em, data, grupo, titulo, versiculo, referencia, texto, autor,
   traducoes, imagem_url, serie_id, ordem_na_serie)
select
  (timestamp '2026-12-21 06:00' at time zone 'Europe/London'),
  date '2026-12-21', null,
  $peniel$Os que esperaram$peniel$,
  $peniel$Agora, Senhor, podes despedir em paz o teu servo, segundo a tua palavra; porque os meus olhos já viram a tua salvação.$peniel$,
  $peniel$Lucas 2:29-30$peniel$,
  $peniel$Cumpre: Isaías 53 e Malaquias 4:2

Quarenta dias depois do nascimento, Maria e José levam Jesus ao templo para apresentá-lo ao Senhor. Ali, dois idosos estavam esperando.

Simeão era justo e piedoso, e esperava a consolação de Israel. O Espírito Santo tinha revelado a ele que não morreria antes de ver o Cristo. Quando viu o menino, tomou-o nos braços e disse que já podia partir em paz, porque os seus olhos tinham visto a salvação.

Ana era profetisa, viúva havia muitos anos, com 84 anos de idade. Ela não saía do templo, adorando com jejuns e orações noite e dia. Quando viu Jesus, começou a dar graças e a falar d'Ele a todos os que esperavam a redenção.

Simeão e Ana representam todos os que esperaram durante os 400 anos de silêncio. Eles não desistiram. E Simeão também disse a Maria algo difícil: uma espada traspassaria a alma dela. A alegria do Natal já trazia a sombra do Servo ferido de Isaías 53.

Esperar em Deus nunca é tempo perdido. Simeão e Ana passaram anos esperando, e Deus os honrou com o privilégio de segurar e anunciar o Salvador.

Para refletir: O que você está esperando de Deus neste fim de ano? Como Simeão e Ana podem inspirar a sua espera?

Oração: Senhor, obrigado por Simeão e Ana, que esperaram com fé. Ensina-me a esperar sem desistir, a orar sem parar e a adorar enquanto aguardo. Que os meus olhos vejam a Tua salvação todos os dias. Amém.

Leitura complementar: Lucas 2:22-38 · Isaías 40:31$peniel$,
  $peniel$Pr. Marcos Brandão$peniel$,
  $peniel${"en": {"titulo": "Those who waited", "referencia": "Luke 2:29-30", "versiculo": "Lord, now lettest thou thy servant depart in peace, according to thy word: for mine eyes have seen thy salvation.", "texto": "Fulfils: Isaiah 53 and Malachi 4:2\n\nForty days after the birth, Mary and Joseph take Jesus to the Temple to present Him to the Lord. There, two elderly people were waiting.\n\nSimeon was righteous and devout, and he was waiting for the consolation of Israel. The Holy Spirit had revealed to him that he would not die before he had seen the Christ. When he saw the child, he took Him in his arms and said that he could now depart in peace, because his eyes had seen salvation.\n\nAnna was a prophetess, widowed for many years, and 84 years old. She never left the Temple, worshipping with fasting and prayer night and day. When she saw Jesus, she began to give thanks and to speak of Him to all who were looking for redemption.\n\nSimeon and Anna represent everyone who waited through the 400 years of silence. They did not give up. And Simeon also told Mary something hard: a sword would pierce her own soul. The joy of Christmas already carried the shadow of the wounded Servant of Isaiah 53.\n\nWaiting on God is never time wasted. Simeon and Anna spent years waiting, and God honoured them with the privilege of holding and announcing the Saviour.\n\nReflect: What are you waiting for from God as this year comes to an end? How can Simeon and Anna inspire your waiting?\n\nPrayer: Lord, thank You for Simeon and Anna, who waited in faith. Teach me to wait without giving up, to pray without ceasing and to worship while I wait. May my eyes see Your salvation every day. Amen.\n\nFurther reading: Luke 2:22-38 · Isaiah 40:31"}, "es": {"titulo": "Los que esperaron", "referencia": "Lucas 2:29-30", "versiculo": "Ahora despides, Señor, a tu siervo, conforme a tu palabra, en paz; porque han visto mis ojos tu salvación.", "texto": "Cumple: Isaías 53 y Malaquías 4:2\n\nCuarenta días después del nacimiento, María y José llevan a Jesús al templo para presentarlo al Señor. Allí, dos ancianos estaban esperando.\n\nSimeón era justo y piadoso, y esperaba la consolación de Israel. El Espíritu Santo le había revelado que no moriría antes de ver al Cristo. Cuando vio al niño, lo tomó en sus brazos y dijo que ya podía partir en paz, porque sus ojos habían visto la salvación.\n\nAna era profetisa, viuda desde hacía muchos años, de 84 años de edad. No se apartaba del templo, sirviendo con ayunos y oraciones de noche y de día. Cuando vio a Jesús, comenzó a dar gracias y a hablar de Él a todos los que esperaban la redención.\n\nSimeón y Ana representan a todos los que esperaron durante los 400 años de silencio. No se rindieron. Y Simeón también le dijo a María algo difícil: una espada traspasaría su alma. La alegría de la Navidad ya traía la sombra del Siervo herido de Isaías 53.\n\nEsperar en Dios nunca es tiempo perdido. Simeón y Ana pasaron años esperando, y Dios los honró con el privilegio de sostener y anunciar al Salvador.\n\nPara reflexionar: ¿Qué estás esperando de Dios en este fin de año? ¿Cómo pueden Simeón y Ana inspirar tu espera?\n\nOración: Señor, gracias por Simeón y Ana, que esperaron con fe. Enséñame a esperar sin rendirme, a orar sin cesar y a adorar mientras aguardo. Que mis ojos vean Tu salvación todos los días. Amén.\n\nLectura complementaria: Lucas 2:22-38 · Isaías 40:31"}, "fr": {"titulo": "Ceux qui ont attendu", "referencia": "Luc 2:29-30", "versiculo": "Maintenant, Seigneur, tu laisses ton serviteur S'en aller en paix, selon ta parole. Car mes yeux ont vu ton salut.", "texto": "Accomplit : Ésaïe 53 et Malachie 4:2\n\nQuarante jours après la naissance, Marie et Joseph portent Jésus au temple pour le présenter au Seigneur. Là, deux personnes âgées attendaient.\n\nSiméon était juste et pieux, et il attendait la consolation d'Israël. Le Saint-Esprit lui avait révélé qu'il ne mourrait pas avant d'avoir vu le Christ. Quand il a vu l'enfant, il l'a pris dans ses bras et a dit qu'il pouvait désormais s'en aller en paix, car ses yeux avaient vu le salut.\n\nAnne était prophétesse, veuve depuis de nombreuses années, âgée de 84 ans. Elle ne quittait pas le temple, servant Dieu nuit et jour dans le jeûne et la prière. Quand elle a vu Jésus, elle s'est mise à louer Dieu et à parler de Lui à tous ceux qui attendaient la délivrance.\n\nSiméon et Anne représentent tous ceux qui ont attendu pendant les 400 ans de silence. Ils n'ont pas abandonné. Et Siméon a aussi dit à Marie quelque chose de difficile : une épée transpercerait son âme. La joie de Noël portait déjà l'ombre du Serviteur blessé d'Ésaïe 53.\n\nAttendre Dieu n'est jamais du temps perdu. Siméon et Anne ont attendu pendant des années, et Dieu les a honorés du privilège de tenir et d'annoncer le Sauveur.\n\nÀ méditer : Qu'attends-tu de Dieu en cette fin d'année ? Comment Siméon et Anne peuvent-ils inspirer ton attente ?\n\nPrière : Seigneur, merci pour Siméon et Anne, qui ont attendu avec foi. Apprends-moi à attendre sans abandonner, à prier sans cesse et à adorer pendant que j'attends. Que mes yeux voient Ton salut chaque jour. Amen.\n\nLecture complémentaire : Luc 2:22-38 · Ésaïe 40:31"}}$peniel$::jsonb,
  null,
  'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid, 9
where not exists (
  select 1 from public.devocionais_agendados
   where data = date '2026-12-21' and serie_id = 'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid
);

-- 22 · 2026-12-23 · Luz para as nações
insert into public.devocionais_agendados
  (publicar_em, data, grupo, titulo, versiculo, referencia, texto, autor,
   traducoes, imagem_url, serie_id, ordem_na_serie)
select
  (timestamp '2026-12-23 06:00' at time zone 'Europe/London'),
  date '2026-12-23', null,
  $peniel$Luz para as nações$peniel$,
  $peniel$E, vendo eles a estrela, alegraram-se com grande e intenso júbilo. Entrando na casa, viram o menino com Maria, sua mãe. Prostrando-se, o adoraram.$peniel$,
  $peniel$Mateus 2:10-11$peniel$,
  $peniel$Cumpre: Gênesis 12:3 e Isaías 9:2

Os primeiros a adorar Jesus foram pastores judeus. Os próximos vieram de muito longe: magos do Oriente, estudiosos dos céus, estrangeiros que não pertenciam ao povo de Israel.

Eles viram uma estrela e viajaram por meses, seguindo um sinal que nem entendiam completamente. Chegaram a Jerusalém perguntando: “Onde está o recém-nascido Rei dos judeus?” E foram os sacerdotes, citando Miqueias, que apontaram para Belém.

Repare no contraste. Os sacerdotes sabiam o versículo certo, mas não andaram dez quilômetros até Belém. Herodes ouviu a notícia e ficou perturbado. Os estrangeiros, que sabiam menos, foram os que chegaram, se prostraram e adoraram.

A promessa feita a Abraão dizia que nele seriam benditas todas as famílias da terra. Isaías disse que o povo em trevas veria grande luz. Os magos são o primeiro sinal de que a luz não era só para Israel. Jesus veio para todas as nações.

Ouro para um rei, incenso para Deus, mirra para quem iria morrer. Até os presentes contavam quem Ele era. Hoje, gente de todos os povos e línguas continua chegando para adorá-Lo, em todos os cantos da terra.

Para refletir: Você conhece a Palavra como os sacerdotes ou adora como os magos? O que você vai oferecer a Jesus neste Natal?

Oração: Senhor Jesus, Luz das nações, obrigado porque a Tua salvação chegou até mim. Não quero apenas saber sobre Ti, quero me prostrar e Te adorar. Recebe o melhor de mim neste Natal. Amém.

Leitura complementar: Mateus 2:1-12 · Isaías 60:1-3$peniel$,
  $peniel$Pr. Marcos Brandão$peniel$,
  $peniel${"en": {"titulo": "A light for the nations", "referencia": "Matthew 2:10-11", "versiculo": "When they saw the star, they rejoiced with exceeding great joy. And when they were come into the house, they saw the young child with Mary his mother, and fell down, and worshipped him.", "texto": "Fulfils: Genesis 12:3 and Isaiah 9:2\n\nThe first to worship Jesus were Jewish shepherds. The next came from far away: wise men from the East, students of the heavens, foreigners who did not belong to the people of Israel.\n\nThey saw a star and travelled for months, following a sign they did not fully understand. They arrived in Jerusalem asking: “Where is he that is born King of the Jews?” And it was the priests, quoting Micah, who pointed them to Bethlehem.\n\nNotice the contrast. The priests knew the right verse, but they did not walk the ten kilometres to Bethlehem. Herod heard the news and was troubled. The foreigners, who knew less, were the ones who arrived, bowed down and worshipped.\n\nThe promise made to Abraham said that in him all the families of the earth would be blessed. Isaiah said that the people in darkness would see a great light. The wise men are the first sign that the light was not only for Israel. Jesus came for all nations.\n\nGold for a king, frankincense for God, myrrh for one who was going to die. Even the gifts told who He was. Today, people from every nation and language are still coming to worship Him, in every corner of the earth.\n\nReflect: Do you know the Word like the priests, or worship like the wise men? What will you offer Jesus this Christmas?\n\nPrayer: Lord Jesus, Light of the nations, thank You that Your salvation has reached me. I do not want just to know about You; I want to bow down and worship You. Receive the best of me this Christmas. Amen.\n\nFurther reading: Matthew 2:1-12 · Isaiah 60:1-3"}, "es": {"titulo": "Luz para las naciones", "referencia": "Mateo 2:10-11", "versiculo": "Y vista la estrella, se regocijaron con muy grande gozo. Y entrando en la casa, vieron al niño con su madre María, y postrándose, le adoraron.", "texto": "Cumple: Génesis 12:3 e Isaías 9:2\n\nLos primeros en adorar a Jesús fueron pastores judíos. Los siguientes vinieron de muy lejos: magos del Oriente, estudiosos de los cielos, extranjeros que no pertenecían al pueblo de Israel.\n\nVieron una estrella y viajaron durante meses, siguiendo una señal que ni siquiera entendían por completo. Llegaron a Jerusalén preguntando: “¿Dónde está el Rey de los judíos, que ha nacido?” Y fueron los sacerdotes, citando a Miqueas, quienes señalaron a Belén.\n\nFíjate en el contraste. Los sacerdotes conocían el versículo correcto, pero no caminaron diez kilómetros hasta Belén. Herodes oyó la noticia y se turbó. Los extranjeros, que sabían menos, fueron los que llegaron, se postraron y adoraron.\n\nLa promesa hecha a Abraham decía que en él serían benditas todas las familias de la tierra. Isaías dijo que el pueblo en tinieblas vería gran luz. Los magos son la primera señal de que la luz no era solo para Israel. Jesús vino para todas las naciones.\n\nOro para un rey, incienso para Dios, mirra para quien iba a morir. Hasta los regalos contaban quién era Él. Hoy, gente de todos los pueblos y lenguas sigue llegando para adorarle, en todos los rincones de la tierra.\n\nPara reflexionar: ¿Conoces la Palabra como los sacerdotes o adoras como los magos? ¿Qué le vas a ofrecer a Jesús en esta Navidad?\n\nOración: Señor Jesús, Luz de las naciones, gracias porque Tu salvación llegó hasta mí. No quiero solo saber acerca de Ti, quiero postrarme y adorarte. Recibe lo mejor de mí en esta Navidad. Amén.\n\nLectura complementaria: Mateo 2:1-12 · Isaías 60:1-3"}, "fr": {"titulo": "Lumière pour les nations", "referencia": "Matthieu 2:10-11", "versiculo": "Quand ils aperçurent l'étoile, ils furent saisis d'une très grande joie. Ils entrèrent dans la maison, virent le petit enfant avec Marie, sa mère, se prosternèrent et l'adorèrent.", "texto": "Accomplit : Genèse 12:3 et Ésaïe 9:1\n\nLes premiers à adorer Jésus ont été des bergers juifs. Les suivants sont venus de très loin : des mages d'Orient, savants qui étudiaient le ciel, étrangers qui n'appartenaient pas au peuple d'Israël.\n\nIls ont vu une étoile et ont voyagé pendant des mois, suivant un signe qu'ils ne comprenaient même pas entièrement. Ils sont arrivés à Jérusalem en demandant : « Où est le roi des Juifs qui vient de naître ? » Et ce sont les prêtres, citant Michée, qui ont désigné Bethléhem.\n\nRemarque le contraste. Les prêtres connaissaient le bon verset, mais n'ont pas fait les dix kilomètres jusqu'à Bethléhem. Hérode a entendu la nouvelle et a été troublé. Les étrangers, qui en savaient moins, sont ceux qui sont arrivés, se sont prosternés et ont adoré.\n\nLa promesse faite à Abraham disait qu'en lui toutes les familles de la terre seraient bénies. Ésaïe avait dit que le peuple dans les ténèbres verrait une grande lumière. Les mages sont le premier signe que la lumière n'était pas seulement pour Israël. Jésus est venu pour toutes les nations.\n\nDe l'or pour un roi, de l'encens pour Dieu, de la myrrhe pour celui qui allait mourir. Même les présents disaient qui Il était. Aujourd'hui, des gens de tous les peuples et de toutes les langues continuent de venir L'adorer, dans tous les coins de la terre.\n\nÀ méditer : Connais-tu la Parole comme les prêtres, ou adores-tu comme les mages ? Qu'offriras-tu à Jésus en ce Noël ?\n\nPrière : Seigneur Jésus, Lumière des nations, merci, car Ton salut est parvenu jusqu'à moi. Je ne veux pas seulement savoir des choses sur Toi, je veux me prosterner et T'adorer. Reçois le meilleur de moi en ce Noël. Amen.\n\nLecture complémentaire : Matthieu 2:1-12 · Ésaïe 60:1-3"}}$peniel$::jsonb,
  null,
  'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid, 10
where not exists (
  select 1 from public.devocionais_agendados
   where data = date '2026-12-23' and serie_id = 'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid
);

-- 23 · 2026-12-25 · Um menino nos nasceu (Natal)
insert into public.devocionais_agendados
  (publicar_em, data, grupo, titulo, versiculo, referencia, texto, autor,
   traducoes, imagem_url, serie_id, ordem_na_serie)
select
  (timestamp '2026-12-25 06:00' at time zone 'Europe/London'),
  date '2026-12-25', null,
  $peniel$Um menino nos nasceu (Natal)$peniel$,
  $peniel$É que hoje vos nasceu, na cidade de Davi, o Salvador, que é Cristo, o Senhor.$peniel$,
  $peniel$Lucas 2:11$peniel$,
  $peniel$Cumpre: Toda a promessa, de Gênesis 3:15 a Malaquias 4:2

Feliz Natal!

Hoje chegamos ao fim de uma longa caminhada. Começamos no Éden, onde Deus prometeu um descendente que venceria o mal. Passamos por Abraão, Isaque, Judá, Moisés, Davi e os profetas. Ouvimos o silêncio de 400 anos. E em Dezembro vimos cada promessa se cumprir, uma após a outra.

O descendente da mulher, prometido no jardim, nasceu de uma virgem. A bênção para todas as famílias, prometida a Abraão, chegou até pastores e magos. O cordeiro que Deus proveria estava deitado numa manjedoura. O cetro de Judá e o trono de Davi encontraram o seu Rei. Belém, a pequena, recebeu o Governante eterno.

Isaías disse: “Um menino nos nasceu, um filho se nos deu.” Repare nas duas partes. Um menino nasceu: Jesus é verdadeiramente humano. Um filho se nos deu: Ele é o presente de Deus para nós. O Natal não é sobre o que nós damos, mas sobre o que Deus nos deu.

Deus cumpriu todas as promessas que fez sobre a primeira vinda de Jesus. Por isso podemos confiar nas promessas que ainda faltam: Ele vai voltar, enxugar toda lágrima e fazer novas todas as coisas.

Que neste dia, no meio da família, da mesa e dos presentes, o seu coração se volte para o maior presente de todos. Ele veio.

Para refletir: Qual das promessas que vimos nestas semanas mais falou ao seu coração? Agradeça a Deus por ela hoje, junto com a sua família.

Oração: Pai, obrigado pelo maior presente de todos: o Teu Filho. Obrigado porque cumpriste cada promessa. Jesus, Tu és o meu Maravilhoso Conselheiro, Deus Forte, Pai da Eternidade e Príncipe da Paz. Nasce de novo no meu coração neste Natal. Em nome de Jesus, amém.

Leitura complementar: Lucas 2:1-20 · 2 Coríntios 1:20 · Apocalipse 21:3-5$peniel$,
  $peniel$Pr. Marcos Brandão$peniel$,
  $peniel${"en": {"titulo": "Unto us a child is born (Christmas)", "referencia": "Luke 2:11", "versiculo": "For unto you is born this day in the city of David a Saviour, which is Christ the Lord.", "texto": "Fulfils: The whole promise, from Genesis 3:15 to Malachi 4:2\n\nHappy Christmas!\n\nToday we reach the end of a long journey. We began in Eden, where God promised a descendant who would overcome evil. We passed through Abraham, Isaac, Judah, Moses, David and the prophets. We heard the 400 years of silence. And in December we saw every promise fulfilled, one after another.\n\nThe descendant of the woman, promised in the garden, was born of a virgin. The blessing for all families, promised to Abraham, reached shepherds and wise men. The lamb that God would provide was lying in a manger. The sceptre of Judah and the throne of David found their King. Bethlehem, the little town, received the eternal Ruler.\n\nIsaiah said: “Unto us a child is born, unto us a son is given.” Notice the two parts. A child is born: Jesus is truly human. A son is given: He is God's gift to us. Christmas is not about what we give, but about what God has given us.\n\nGod kept every promise He made about Jesus' first coming. That is why we can trust the promises still to come: He will return, wipe away every tear and make all things new.\n\nToday, surrounded by family, the table and the presents, may your heart turn to the greatest gift of all. He came.\n\nReflect: Which of the promises we have looked at over these weeks has spoken most to your heart? Thank God for it today, together with your family.\n\nPrayer: Father, thank You for the greatest gift of all: Your Son. Thank You for keeping every promise. Jesus, You are my Wonderful Counsellor, Mighty God, Everlasting Father and Prince of Peace. Be born anew in my heart this Christmas. In Jesus' name, amen.\n\nFurther reading: Luke 2:1-20 · 2 Corinthians 1:20 · Revelation 21:3-5"}, "es": {"titulo": "Un niño nos es nacido (Navidad)", "referencia": "Lucas 2:11", "versiculo": "Que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor.", "texto": "Cumple: Toda la promesa, de Génesis 3:15 a Malaquías 4:2\n\n¡Feliz Navidad!\n\nHoy llegamos al final de un largo camino. Comenzamos en el Edén, donde Dios prometió un descendiente que vencería el mal. Pasamos por Abraham, Isaac, Judá, Moisés, David y los profetas. Escuchamos el silencio de 400 años. Y en diciembre vimos cumplirse cada promesa, una tras otra.\n\nEl descendiente de la mujer, prometido en el huerto, nació de una virgen. La bendición para todas las familias, prometida a Abraham, llegó hasta pastores y magos. El cordero que Dios proveería estaba acostado en un pesebre. El cetro de Judá y el trono de David encontraron a su Rey. Belén, la pequeña, recibió al Gobernante eterno.\n\nIsaías dijo: “Un niño nos es nacido, hijo nos es dado.” Fíjate en las dos partes. Un niño nació: Jesús es verdaderamente humano. Un hijo nos fue dado: Él es el regalo de Dios para nosotros. La Navidad no se trata de lo que nosotros damos, sino de lo que Dios nos dio.\n\nDios cumplió todas las promesas que hizo sobre la primera venida de Jesús. Por eso podemos confiar en las promesas que aún faltan: Él volverá, enjugará toda lágrima y hará nuevas todas las cosas.\n\nQue en este día, en medio de la familia, de la mesa y de los regalos, tu corazón se vuelva hacia el regalo más grande de todos. Él vino.\n\nPara reflexionar: ¿Cuál de las promesas que vimos en estas semanas le habló más a tu corazón? Dale gracias a Dios por ella hoy, junto con tu familia.\n\nOración: Padre, gracias por el regalo más grande de todos: Tu Hijo. Gracias porque cumpliste cada promesa. Jesús, Tú eres mi Admirable Consejero, Dios Fuerte, Padre Eterno y Príncipe de Paz. Nace de nuevo en mi corazón en esta Navidad. En el nombre de Jesús, amén.\n\nLectura complementaria: Lucas 2:1-20 · 2 Corintios 1:20 · Apocalipsis 21:3-5"}, "fr": {"titulo": "Un enfant nous est né (Noël)", "referencia": "Luc 2:11", "versiculo": "C'est qu'aujourd'hui, dans la ville de David, il vous est né un Sauveur, qui est le Christ, le Seigneur.", "texto": "Accomplit : Toute la promesse, de Genèse 3:15 à Malachie 4:2\n\nJoyeux Noël !\n\nAujourd'hui, nous arrivons au terme d'une longue marche. Nous avons commencé en Éden, où Dieu a promis un descendant qui vaincrait le mal. Nous sommes passés par Abraham, Isaac, Juda, Moïse, David et les prophètes. Nous avons entendu le silence de 400 ans. Et en décembre, nous avons vu chaque promesse s'accomplir, l'une après l'autre.\n\nLe descendant de la femme, promis dans le jardin, est né d'une vierge. La bénédiction pour toutes les familles, promise à Abraham, est parvenue jusqu'aux bergers et aux mages. L'agneau auquel Dieu pourvoirait était couché dans une crèche. Le sceptre de Juda et le trône de David ont trouvé leur Roi. Bethléhem, la petite, a accueilli le Souverain éternel.\n\nÉsaïe a dit : « Un enfant nous est né, un fils nous est donné. » Remarque les deux parties. Un enfant est né : Jésus est vraiment humain. Un fils nous est donné : Il est le cadeau de Dieu pour nous. Noël ne parle pas de ce que nous donnons, mais de ce que Dieu nous a donné.\n\nDieu a accompli toutes les promesses qu'Il avait faites au sujet de la première venue de Jésus. C'est pourquoi nous pouvons nous fier aux promesses qui restent à accomplir : Il reviendra, Il essuiera toute larme et Il fera toutes choses nouvelles.\n\nQu'en ce jour, au milieu de la famille, de la table et des cadeaux, ton cœur se tourne vers le plus grand cadeau de tous. Il est venu.\n\nÀ méditer : Laquelle des promesses que nous avons vues ces dernières semaines a le plus parlé à ton cœur ? Remercie Dieu pour elle aujourd'hui, avec ta famille.\n\nPrière : Père, merci pour le plus grand cadeau de tous : Ton Fils. Merci d'avoir accompli chacune de Tes promesses. Jésus, Tu es mon Conseiller admirable, Dieu puissant, Père éternel et Prince de la paix. Nais de nouveau dans mon cœur en ce Noël. Au nom de Jésus, amen.\n\nLecture complémentaire : Luc 2:1-20 · 2 Corinthiens 1:20 · Apocalypse 21:3-5"}}$peniel$::jsonb,
  null,
  'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid, 11
where not exists (
  select 1 from public.devocionais_agendados
   where data = date '2026-12-25' and serie_id = 'b3846c38-c825-4460-b279-fa4ec8df620f'::uuid
);

commit;

-- Conferência
select to_char(a.data, 'DD/MM/YYYY') as data,
       to_char(a.publicar_em at time zone 'Europe/London', 'DD/MM HH24:MI') as publica_londres,
       s.titulo as serie, a.ordem_na_serie as ordem, a.titulo,
       a.imagem_url,
       (select string_agg(k, ', ' order by k) from jsonb_object_keys(a.traducoes) k) as traducoes
  from public.devocionais_agendados a
  join public.devocional_series s on s.id = a.serie_id
 order by a.data;
